function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length, n = grid[0].length;
    const TOP = m * n;
    const parent = new Array(m * n + 1);
    const size = new Array(m * n + 1).fill(1);
    for (let i = 0; i <= m * n; i++) parent[i] = i;

    function find(x: number): number {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    function union(a: number, b: number): void {
        const ra = find(a), rb = find(b);
        if (ra === rb) return;
        parent[ra] = rb;
        size[rb] += size[ra];
    }

    // copy grid and remove hits
    const g: number[][] = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        g[r][c] -= 1;
    }

    const idx = (r: number, c: number) => r * n + c;
    const dirs = [[0,1],[0,-1],[1,0],[-1,0]];

    // build union-find on remaining grid
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] === 1) {
                if (r === 0) union(idx(r,c), TOP);
                for (const [dr, dc] of dirs) {
                    const nr = r + dr, nc = c + dc;
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                        union(idx(r,c), idx(nr,nc));
                    }
                }
            }
        }
    }

    const result = new Array(hits.length).fill(0);

    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];
        g[r][c] += 1;
        if (g[r][c] !== 1) {
            // no brick was originally there
            continue;
        }
        const prevTop = size[find(TOP)];
        if (r === 0) union(idx(r,c), TOP);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(idx(r,c), idx(nr,nc));
            }
        }
        const newTop = size[find(TOP)];
        result[i] = Math.max(0, newTop - prevTop - 1);
    }

    return result;
};
```

