function numFactoredBinaryTrees(arr: number[]): number {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);
    const dp = new Map<number, bigint>();
    for (let i = 0; i < arr.length; i++) {
        let count = 1n;
        for (let j = 0; j < i; j++) {
            if (arr[i] % arr[j] === 0) {
                const other = arr[i] / arr[j];
                if (dp.has(other)) {
                    count = (count + dp.get(arr[j])! * dp.get(other)!) % MOD;
                }
            }
        }
        dp.set(arr[i], count);
    }
    let total = 0n;
    for (const v of dp.values()) {
        total = (total + v) % MOD;
    }
    return Number(total);
};
```

