function countVowelPermutation(n: number): number {
    const MOD = 1000000007n;
    let a = 1n, e = 1n, i = 1n, o = 1n, u = 1n;
    for (let k = 1; k < n; k++) {
        const na = (e + i + u) % MOD;
        const ne = (a + i) % MOD;
        const ni = (e + o) % MOD;
        const no = i;
        const nu = (i + o) % MOD;
        a = na; e = ne; i = ni; o = no; u = nu;
    }
    return Number((a + e + i + o + u) % MOD);
};
