class MKAverage {
    private m: number;
    private k: number;
    private queue: number[];
    private countTree: number[]; // BIT for counts
    private sumTree: number[];   // BIT for sums
    private MAXV = 100001;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
        this.queue = [];
        this.countTree = new Array(this.MAXV + 1).fill(0);
        this.sumTree = new Array(this.MAXV + 1).fill(0);
    }

    private update(i: number, deltaCount: number, deltaSum: number): void {
        for (; i <= this.MAXV; i += i & (-i)) {
            this.countTree[i] += deltaCount;
            this.sumTree[i] += deltaSum;
        }
    }

    // prefix count up to index i (inclusive)
    private queryCount(i: number): number {
        let res = 0;
        for (; i > 0; i -= i & (-i)) res += this.countTree[i];
        return res;
    }

    private querySum(i: number): number {
        let res = 0;
        for (; i > 0; i -= i & (-i)) res += this.sumTree[i];
        return res;
    }

    addElement(num: number): void {
        this.queue.push(num);
        this.update(num, 1, num);
        if (this.queue.length > this.m) {
            const removed = this.queue.shift()!;
            this.update(removed, -1, -removed);
        }
    }

    // find sum of smallest `cnt` elements in the tree
    private sumOfSmallest(cnt: number): number {
        if (cnt <= 0) return 0;
        let idx = 0;
        let remaining = cnt;
        let sum = 0;
        // binary lifting on BIT
        let logn = 1;
        while ((1 << logn) <= this.MAXV) logn++;
        logn--;
        for (let pw = logn; pw >= 0; pw--) {
            const next = idx + (1 << pw);
            if (next <= this.MAXV && this.countTree[next] < remaining) {
                idx = next;
                remaining -= this.countTree[next];
                sum += this.sumTree[next];
            }
        }
        // now idx is largest index with prefix count < cnt
        // the element at idx+1 provides remaining elements
        const valIndex = idx + 1;
        sum += remaining * valIndex;
        return sum;
    }

    calculateMKAverage(): number {
        if (this.queue.length < this.m) return -1;
        const total = this.querySum(this.MAXV);
        const smallestK = this.sumOfSmallest(this.k);
        const largestK = this.sumOfSmallest(this.m) - this.sumOfSmallest(this.m - this.k);
        const middleSum = total - smallestK - largestK;
        const count = this.m - 2 * this.k;
        return Math.floor(middleSum / count);
    }
}

/**
 * Your MKAverage object will be instantiated and called as such:
 * var obj = new MKAverage(m, k)
 * obj.addElement(num)
 * var param_2 = obj.calculateMKAverage()
 */
```

