function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const f = (s: string): number => {
        let min = 'z';
        for (const c of s) if (c < min) min = c;
        let cnt = 0;
        for (const c of s) if (c === min) cnt++;
        return cnt;
    };
    const wf = words.map(f).sort((a, b) => a - b);
    return queries.map(q => {
        const val = f(q);
        // count words with f(W) > val
        let lo = 0, hi = wf.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (wf[mid] <= val) lo = mid + 1;
            else hi = mid;
        }
        return wf.length - lo;
    });
};
```

