function maximumANDSum(nums: number[], numSlots: number): number {
    const n = nums.length;
    // each slot has 2 capacity, represent state in base 3
    const total = Math.pow(3, numSlots);
    const dp = new Array(total).fill(-1);
    dp[0] = 0;
    let ans = 0;
    for (let mask = 0; mask < total; mask++) {
        if (dp[mask] < 0) continue;
        // count how many numbers placed
        let placed = 0;
        let temp = mask;
        for (let s = 0; s < numSlots; s++) {
            placed += temp % 3;
            temp = Math.floor(temp / 3);
        }
        if (placed >= n) {
            ans = Math.max(ans, dp[mask]);
            continue;
        }
        const num = nums[placed];
        let power = 1;
        for (let s = 0; s < numSlots; s++) {
            const digit = Math.floor(mask / power) % 3;
            if (digit < 2) {
                const newMask = mask + power;
                const val = dp[mask] + (num & (s + 1));
                if (val > dp[newMask]) dp[newMask] = val;
            }
            power *= 3;
        }
    }
    return ans;
};
