function maxEqualFreq(nums: number[]): number {
    const count = new Map<number, number>();
    const freqCount = new Map<number, number>();
    let maxFreq = 0;
    let ans = 0;

    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        const oldC = count.get(x) || 0;
        if (oldC > 0) {
            freqCount.set(oldC, (freqCount.get(oldC) || 0) - 1);
        }
        const newC = oldC + 1;
        count.set(x, newC);
        freqCount.set(newC, (freqCount.get(newC) || 0) + 1);
        maxFreq = Math.max(maxFreq, newC);

        const len = i + 1;
        let valid = false;

        // Case 1: all counts are 1 (remove any one leaves counts 1... actually remove one to make all 0 or all same)
        // maxFreq == 1: all appear once, remove one -> rest appear once
        if (maxFreq === 1) {
            valid = true;
        }
        // Case 2: one element has freq maxFreq==1 and rest have freq maxFreq-1
        else if ((freqCount.get(1) || 0) === 1 && 
                 (freqCount.get(maxFreq) || 0) * maxFreq === len - 1) {
            // there's exactly one number with count 1
            valid = true;
        }
        // Case 3: one number has count maxFreq, rest have count maxFreq-1, remove one from that number
        else if ((freqCount.get(maxFreq) || 0) === 1 && 
                 (freqCount.get(maxFreq - 1) || 0) * (maxFreq - 1) === len - maxFreq) {
            valid = true;
        }

        if (valid) ans = len;
    }

    return ans;
};
