function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
    const n = fruits.length;
    let ans = 0;
    let left = 0;
    let sum = 0;
    for (let right = 0; right < n; right++) {
        sum += fruits[right][1];
        while (left <= right) {
            const l = fruits[left][0];
            const r = fruits[right][0];
            // cost: go left first then right, or right first then left
            const cost = Math.min(
                Math.abs(startPos - l) + Math.abs(r - l),
                Math.abs(r - startPos) + Math.abs(r - l)
            );
            if (cost <= k) break;
            sum -= fruits[left][1];
            left++;
        }
        if (left <= right) {
            ans = Math.max(ans, sum);
        }
    }
    return ans;
};
