function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const initSet = new Set(initial);

    // For each clean node, find set of initial nodes that can infect it
    // through paths using only clean nodes.
    // We'll do BFS from each initial node through clean nodes.

    // reachBy[node] = set of initial nodes reaching this clean node
    const reachBy: Set<number>[] = Array.from({length: n}, () => new Set<number>());

    for (const src of initial) {
        // BFS from src, but only traverse into clean (non-initial) nodes
        const visited = new Array(n).fill(false);
        const queue: number[] = [];
        // start: neighbors of src that are clean
        visited[src] = true;
        for (let j = 0; j < n; j++) {
            if (graph[src][j] === 1 && j !== src && !initSet.has(j) && !visited[j]) {
                visited[j] = true;
                queue.push(j);
            }
        }
        let head = 0;
        while (head < queue.length) {
            const cur = queue[head++];
            reachBy[cur].add(src);
            for (let j = 0; j < n; j++) {
                if (graph[cur][j] === 1 && j !== cur && !initSet.has(j) && !visited[j]) {
                    visited[j] = true;
                    queue.push(j);
                }
            }
        }
    }

    // count saved nodes per initial node (clean nodes reachable by only that one)
    const saved = new Map<number, number>();
    for (const s of initial) saved.set(s, 0);

    for (let node = 0; node < n; node++) {
        if (initSet.has(node)) continue;
        if (reachBy[node].size === 1) {
            const only = [...reachBy[node]][0];
            saved.set(only, (saved.get(only) || 0) + 1);
        }
    }

    let best = -1;
    let bestSaved = -1;
    const sorted = [...initial].sort((a, b) => a - b);
    for (const s of sorted) {
        const sv = saved.get(s) || 0;
        if (sv > bestSaved) {
            bestSaved = sv;
            best = s;
        }
    }
    return best;
};
