function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const adj: [number, number][][] = Array.from({length: n}, () => []);
    for (const [x, y, t] of edges) {
        adj[x].push([y, t]);
        adj[y].push([x, t]);
    }
    // dp[node][time] = min cost, but we iterate over time dimension
    const INF = Infinity;
    // dp[t][node] = min cost to reach node using exactly <= t time
    // Use dp where dp[node] keyed by time
    const dp: number[][] = Array.from({length: maxTime + 1}, () => new Array(n).fill(INF));
    dp[0][0] = passingFees[0];
    for (let t = 0; t <= maxTime; t++) {
        for (let u = 0; u < n; u++) {
            if (dp[t][u] === INF) continue;
            for (const [v, time] of adj[u]) {
                const nt = t + time;
                if (nt > maxTime) continue;
                const nc = dp[t][u] + passingFees[v];
                if (nc < dp[nt][v]) dp[nt][v] = nc;
            }
        }
    }
    let ans = INF;
    for (let t = 0; t <= maxTime; t++) {
        if (dp[t][n - 1] < ans) ans = dp[t][n - 1];
    }
    return ans === INF ? -1 : ans;
};
