function maxCompatibilitySum(students: number[][], mentors: number[][]): number {
    const m = students.length;
    const n = students[0].length;
    const score: number[][] = [];
    for (let i = 0; i < m; i++) {
        score.push([]);
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) s++;
            }
            score[i].push(s);
        }
    }
    const dp = new Array(1 << m).fill(-1);
    dp[0] = 0;
    let best = 0;
    for (let mask = 0; mask < (1 << m); mask++) {
        if (dp[mask] < 0) continue;
        let cnt = 0;
        for (let b = 0; b < m; b++) if (mask & (1 << b)) cnt++;
        if (cnt === m) {
            best = Math.max(best, dp[mask]);
            continue;
