        const student = cnt;
        for (let j = 0; j < m; j++) {
            if (!(mask & (1 << j))) {
                const nm = mask | (1 << j);
                dp[nm] = Math.max(dp[nm], dp[mask] + score[student][j]);
            }
        }
    }
    return best;
