function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    const helper = (L: number, M: number): number => {
        let res = 0;
        let maxL = 0;
        for (let i = L + M; i <= n; i++) {
            maxL = Math.max(maxL, prefix[i - M] - prefix[i - M - L]);
            res = Math.max(res, maxL + prefix[i] - prefix[i - M]);
        }
        return res;
    };

    return Math.max(helper(firstLen, secondLen), helper(secondLen, firstLen));
};
