function numOfWays(nums: number[]): number {
    const MOD = 1000000007n;
    const n = nums.length;

    // Precompute binomial coefficients using Pascal's triangle mod MOD
    const C: bigint[][] = [];
    for (let i = 0; i <= n; i++) {
        C.push(new Array(n + 1).fill(0n));
        C[i][0] = 1n;
        for (let j = 1; j <= i; j++) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
    }

    function count(arr: number[]): bigint {
        if (arr.length <= 2) return 1n;
        const root = arr[0];
        const left: number[] = [];
        const right: number[] = [];
        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < root) left.push(arr[i]);
            else right.push(arr[i]);
        }
        const l = left.length;
        const r = right.length;
        const ways = C[l + r][l];
        return (ways * count(left) % MOD) * count(right) % MOD;
    }

    const result = (count(nums) - 1n + MOD) % MOD;
    return Number(result);
};
