function maxSizeSlices(slices: number[]): number {
    const total = slices.length;
    const n = total / 3;

    const helper = (arr: number[], k: number): number => {
        const m = arr.length;
        // dp[i][j]: max sum considering first i elements, picking j, non-adjacent
        const dp: number[][] = Array.from({length: m + 1}, () => new Array(k + 1).fill(0));
        for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= k; j++) {
                const notPick = dp[i - 1][j];
                const pick = (i >= 2 ? dp[i - 2][j - 1] : 0) + arr[i - 1];
                dp[i][j] = Math.max(notPick, pick);
            }
        }
        return dp[m][k];
    };

    // Exclude first, or exclude last, to break circular adjacency
    const case1 = helper(slices.slice(1), n);
    const case2 = helper(slices.slice(0, total - 1), n);

    return Math.max(case1, case2);
};
