function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const full = (1 << n) - 1;
    // dp[mask] = [sessions, remaining time in current session]
    const dp: [number, number][] = new Array(1 << n);
    dp[0] = [1, 0];
    for (let mask = 1; mask <= full; mask++) {
        dp[mask] = [Infinity, 0];
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                const prev = dp[mask ^ (1 << i)];
                let sessions = prev[0];
                let rem = prev[1];
                if (rem >= tasks[i]) {
                    rem -= tasks[i];
                } else {
                    sessions += 1;
                    rem = sessionTime - tasks[i];
                }
                const cur = dp[mask];
                if (sessions < cur[0] || (sessions === cur[0] && rem > cur[1])) {
                    dp[mask] = [sessions, rem];
                }
            }
        }
    }
    return dp[full][0];
};
