function nextGreaterElements(nums: number[]): number[] {
    const n = nums.length;
    const res = new Array(n).fill(-1);
    const stack: number[] = [];
    for (let i = 0; i < 2 * n; i++) {
        const idx = i % n;
        while (stack.length && nums[stack[stack.length - 1]] < nums[idx]) {
            res[stack.pop()!] = nums[idx];
        }
        if (i < n) stack.push(idx);
    }
    return res;
};
