function medianSlidingWindow(nums: number[], k: number): number[] {
    const result: number[] = [];
    const n = nums.length;
    // sorted window
    const window: number[] = [];

    const bisectLeft = (arr: number[], x: number): number => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };

    for (let i = 0; i < n; i++) {
        // insert nums[i]
        const pos = bisectLeft(window, nums[i]);
        window.splice(pos, 0, nums[i]);

        if (window.length > k) {
            // remove nums[i-k]
            const rp = bisectLeft(window, nums[i - k]);
            window.splice(rp, 1);
        }

        if (window.length === k) {
            let median: number;
            if (k % 2 === 1) {
                median = window[(k - 1) >> 1];
            } else {
                median = (window[k / 2 - 1] + window[k / 2]) / 2;
            }
            result.push(median);
        }
    }

    return result;
};
