function minStickers(stickers: string[], target: string): number {
    const stickerCounts: number[][] = stickers.map(s => {
        const c = new Array(26).fill(0);
        for (const ch of s) c[ch.charCodeAt(0) - 97]++;
        return c;
    });

    const memo = new Map<string, number>();

    function dp(remaining: string): number {
        if (remaining.length === 0) return 0;
        if (memo.has(remaining)) return memo.get(remaining)!;

        const targetCount = new Array(26).fill(0);
        for (const ch of remaining) targetCount[ch.charCodeAt(0) - 97]++;

        let result = Infinity;

        for (const sc of stickerCounts) {
            // optimization: only consider stickers that contain the first char
            if (sc[remaining.charCodeAt(0) - 97] === 0) continue;

            let newRemaining = '';
            for (let i = 0; i < 26; i++) {
                const need = Math.max(0, targetCount[i] - sc[i]);
                if (need > 0) {
                    newRemaining += String.fromCharCode(97 + i).repeat(need);
                }
            }

            const sub = dp(newRemaining);
            if (sub !== -1) {
                result = Math.min(result, 1 + sub);
            }
        }

        const ans = result === Infinity ? -1 : result;
        memo.set(remaining, ans);
        return ans;
    }

    return dp(target);
};
