function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const parent = new Array(4 * n * n);
    for (let i = 0; i < parent.length; i++) parent[i] = i;

    function find(x: number): number {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a: number, b: number): void {
        parent[find(a)] = find(b);
    }

    // 4 triangles per cell: 0=top, 1=right, 2=bottom, 3=left
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const base = 4 * (r * n + c);
            const ch = grid[r][c];
            if (ch === '/') {
                union(base + 0, base + 3);
                union(base + 1, base + 2);
            } else if (ch === '\\') {
                union(base + 0, base + 1);
                union(base + 2, base + 3);
            } else {
                union(base + 0, base + 1);
                union(base + 1, base + 2);
                union(base + 2, base + 3);
            }
            // connect right cell's left with this right
            if (c + 1 < n) {
                const rightBase = 4 * (r * n + c + 1);
                union(base + 1, rightBase + 3);
            }
            // connect bottom cell's top with this bottom
            if (r + 1 < n) {
                const downBase = 4 * ((r + 1) * n + c);
                union(base + 2, downBase + 0);
            }
        }
    }

    let count = 0;
    for (let i = 0; i < parent.length; i++) {
        if (find(i) === i) count++;
    }
    return count;
};
