function sortByBits(arr: number[]): number[] {
    const bits = (n: number): number => {
        let c = 0;
        while (n) { c += n & 1; n >>= 1; }
        return c;
    };
    return arr.slice().sort((a, b) => {
        const ba = bits(a), bb = bits(b);
        return ba !== bb ? ba - bb : a - b;
    });
};
