function sumOddLengthSubarrays(arr: number[]): number {
    const n = arr.length;
    let sum = 0;
    for (let i = 0; i < n; i++) {
        const total = (i + 1) * (n - i);
        const odd = Math.ceil(total / 2);
        sum += odd * arr[i];
    }
    return sum;
};
