function suggestedProducts(products: string[], searchWord: string): string[][] {
    products.sort();
    const result: string[][] = [];
    let prefix = "";
    for (const ch of searchWord) {
        prefix += ch;
        const matches: string[] = [];
        for (const p of products) {
            if (p.startsWith(prefix)) {
                matches.push(p);
                if (matches.length === 3) break;
            }
        }
        result.push(matches);
    }
    return result;
};
