    const maxLen = result.length;

    // leading chars can't be zero
    const nonZero = new Set<string>();
    for (const w of allWords) {
        if (w.length > 1) nonZero.add(w[0]);
    }

    const charToDigit = new Map<string, number>();
    const usedDigits = new Array(10).fill(false);

    // dfs over columns from rightmost
    function dfs(col: number, rowIndex: number, carry: number): boolean {
        if (col === maxLen) {
            return carry === 0;
        }
        if (rowIndex === words.length) {
            // process result char at this column
            const rlen = result.length;
            const rChar = col < rlen ? result[rlen - 1 - col] : null;
            // sum so far is carry; we need to determine result digit
            const targetDigit = carry % 10;
            const newCarry = Math.floor(carry / 10);
            if (rChar === null) {
                // result has no char here; must have digit 0 effectively, but nothing to assign
                if (targetDigit !== 0) return false;
                return dfs(col + 1, 0, newCarry);
            }
            if (charToDigit.has(rChar)) {
                if (charToDigit.get(rChar) !== targetDigit) return false;
                return dfs(col + 1, 0, newCarry);
            } else {
                if (usedDigits[targetDigit]) return false;
                if (targetDigit === 0 && nonZero.has(rChar)) return false;
                charToDigit.set(rChar, targetDigit);
                usedDigits[targetDigit] = true;
                const res = dfs(col + 1, 0, newCarry);
                charToDigit.delete(rChar);
                usedDigits[targetDigit] = false;
                return res;
            }
        }
        // process words[rowIndex] at this column
        const w = words[rowIndex];
        if (col >= w.length) {
            return dfs(col, rowIndex + 1, carry);
        }
        const c = w[w.length - 1 - col];
        if (charToDigit.has(c)) {
            return dfs(col, rowIndex + 1, carry + charToDigit.get(c)!);
        } else {
            for (let d = 0; d <= 9; d++) {
