function validateBinaryTreeNodes(n: number, leftChild: number[], rightChild: number[]): boolean {
    const indeg = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        if (leftChild[i] !== -1) {
            if (++indeg[leftChild[i]] > 1) return false;
        }
        if (rightChild[i] !== -1) {
            if (++indeg[rightChild[i]] > 1) return false;
        }
    }
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }
    if (root === -1) return false;
    const visited = new Array(n).fill(false);
    const stack = [root];
    let count = 0;
    while (stack.length) {
        const node = stack.pop()!;
        if (visited[node]) return false;
        visited[node] = true;
        count++;
        if (leftChild[node] !== -1) stack.push(leftChild[node]);
        if (rightChild[node] !== -1) stack.push(rightChild[node]);
    }
    return count === n;
