function abbreviateProduct(left: number, right: number): string {
    // Count trailing zeros from factors of 2 and 5
    let count2 = 0, count5 = 0;
    for (let i = left; i <= right; i++) {
        let n = i;
        while (n % 2 === 0) { n = Math.floor(n / 2); count2++; }
        while (n % 5 === 0) { n = Math.floor(n / 5); count5++; }
    }
    const C = Math.min(count2, count5);

    // Compute suffix: last digits after removing trailing zeros
    // Use BigInt, keep last ~13 digits, remove trailing zeros progressively
    let suffix = 1n;
    let removed2 = 0, removed5 = 0;
    const MOD = 10n ** 20n; // keep enough digits
    for (let i = left; i <= right; i++) {
        suffix *= BigInt(i);
        // remove trailing zeros up to C total
        while (suffix % 10n === 0n && removed2 + removed5 < 2 * C) {
            suffix /= 10n;
            removed2++; removed5++;
        }
        suffix %= MOD;
    }
    // Now remove exactly the remaining trailing zeros to reach C
    // Actually we removed pairs; we need to remove C total trailing zeros from full product
    // Divide out remaining factors: remove C zeros total. We've been removing when visible.
    // To be safe, remove remaining trailing zeros to get to C
    // Count how many zeros still need removing
    let zerosRemoved = removed2; // since we removed in pairs, removed2==removed5
    while (zerosRemoved < C && suffix % 10n === 0n) {
        suffix /= 10n;
        zerosRemoved++;
    }
    // If still trailing zeros remain but we've reached C, keep them (they are significant)
    // suffix now holds last up to ~20 digits of product with C trailing zeros removed

    // Determine total number of digits using logarithms
    let logSum = 0;
    for (let i = left; i <= right; i++) {
        logSum += Math.log10(i);
    }
    // total digits of full product (before removing zeros)
    const totalDigits = Math.floor(logSum) + 1;
    // digits after removing C trailing zeros
    const d = totalDigits - C;

    const Cstr = C.toString();

    if (d <= 10) {
        // suffix holds the full number (digits <= 10 fits easily, but suffix kept 20 digits)
        // get last d-ish digits — actually full value
        let s = suffix.toString();
        return s + "e" + Cstr + " ";
    } else {
        // prefix: first 5 digits
        const frac = logSum - Math.floor(logSum);
        const lead = Math.pow(10, frac + 4); // 5 significant digits
        let first5 = Math.floor(lead).toString();
        // ensure 5 digits
        first5 = first5.substring(0, 5);

        // suffix: last 5 digits
        let sfx = suffix.toString();
        if (sfx.length > 5) {
            sfx = sfx.substring(sfx.length - 5);
        } else {
            sfx = sfx.padStart(5, '0');
        }

        return first5 + "..." + sfx + "e" + Cstr + " ";
    }
};
