function ambiguousCoordinates(s: string): string[] {
    const digits = s.slice(1, s.length - 1);
    const n = digits.length;
    const result: string[] = [];

    const makeNumbers = (str: string): string[] => {
        const len = str.length;
        const res: string[] = [];
        // no decimal point
        if (len === 1 || str[0] !== '0') {
            res.push(str);
        }
        // with decimal point
        for (let i = 1; i < len; i++) {
            const intPart = str.slice(0, i);
            const decPart = str.slice(i);
            // intPart valid: no leading zero unless single '0'
            if (intPart.length > 1 && intPart[0] === '0') continue;
            // decPart valid: no trailing zero
            if (decPart[decPart.length - 1] === '0') continue;
            res.push(intPart + '.' + decPart);
        }
        return res;
    };

    for (let i = 1; i < n; i++) {
        const left = digits.slice(0, i);
        const right = digits.slice(i);
        const leftNums = makeNumbers(left);
        const rightNums = makeNumbers(right);
        for (const l of leftNums) {
            for (const r of rightNums) {
                result.push(`(${l}, ${r})`);
            }
        }
    }

    return result;
};
